INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9401, 'តើរូបមន្តសម្រាប់គណនាផ្ទៃក្រឡាប្រលេឡូក្រាមដែលមានបាត \(b\) និងកម្ពស់ \(h\) ណាត្រឹមត្រូវ?', 'g8-12ddd0273b.svg', '["\\(S = b^2 \\times h\\)", "\\(S = b \\times h\\)", "\\(S = 2(b + h)\\)", "\\(S = \\dfrac{b \\times h}{2}\\)"]', 1, NULL, 1, 'mcq', 'ផ្ទៃក្រឡាប្រលេឡូក្រាមស្មើផលគុណរវាងបាតនិងកម្ពស់ត្រូវគ្នា ៖ \(S = b \times h\)', 'ផ្ទៃក្រឡាពហុកោណ', 'easy', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
