INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9402, 'តើរូបមន្តសម្រាប់គណនាផ្ទៃក្រឡាចតុកោណព្នាយដែលមានបាតទាំងពីរ \(a, b\) និងកម្ពស់ \(h\) ណាត្រឹមត្រូវ?', 'g8-7d9add613a.svg', '["\\(S = \\dfrac{a + b}{h}\\)", "\\(S = \\dfrac{(a + b) \\times h}{2}\\)", "\\(S = (a + b) \\times h\\)", "\\(S = \\dfrac{a \\times b \\times h}{2}\\)"]', 1, NULL, 1, 'mcq', 'ផ្ទៃក្រឡាចតុកោណព្នាយស្មើកន្លះផលបូកបាតទាំងពីរគុណនឹងកម្ពស់ ៖ \(S = \dfrac{(a+b)h}{2}\)', 'ផ្ទៃក្រឡាពហុកោណ', 'easy', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
