INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9403, 'តើរូបមន្តសម្រាប់គណនាផ្ទៃក្រឡាចតុកោណស្មើដែលមានអង្កត់ទ្រូង \(d_1\) និង \(d_2\) ណាត្រឹមត្រូវ?', 'g8-1c3519bad0.svg', '["\\(S = \\dfrac{d_1 + d_2}{2}\\)", "\\(S = \\dfrac{d_1 \\times d_2}{2}\\)", "\\(S = d_1 \\times d_2\\)", "\\(S = 2(d_1 + d_2)\\)"]', 1, NULL, 1, 'mcq', 'ផ្ទៃក្រឡាចតុកោណស្មើស្មើកន្លះផលគុណនៃអង្កត់ទ្រូងទាំងពីរ ៖ \(S = \dfrac{d_1 \times d_2}{2}\)', 'ផ្ទៃក្រឡាពហុកោណ', 'easy', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9404, 'ប្រលេឡូក្រាមមួយមានបាត \(8\ \text{cm}\) និងកម្ពស់ត្រូវគ្នា \(5\ \text{cm}\)។ គណនាផ្ទៃក្រឡារបស់វា។', NULL, '["\\(80\\ \\text{cm}^2\\)", "\\(26\\ \\text{cm}^2\\)", "\\(40\\ \\text{cm}^2\\)", "\\(20\\ \\text{cm}^2\\)"]', 2, NULL, 1, 'mcq', '\(S = b \times h = 8 \times 5 = 40\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'easy', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9405, 'ចតុកោណព្នាយមួយមានបាតតូច \(6\ \text{cm}\), បាតធំ \(10\ \text{cm}\) និងកម្ពស់ \(4\ \text{cm}\)។ គណនាផ្ទៃក្រឡា។', NULL, '["\\(32\\ \\text{cm}^2\\)", "\\(40\\ \\text{cm}^2\\)", "\\(64\\ \\text{cm}^2\\)", "\\(24\\ \\text{cm}^2\\)"]', 0, NULL, 1, 'mcq', '\(S = \dfrac{(6 + 10) \times 4}{2} = \dfrac{16 \times 4}{2} = 32\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'easy', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9406, 'ចតុកោណស្មើមួយមានអង្កត់ទ្រូងទាំងពីរប្រវែង \(10\ \text{cm}\) និង \(8\ \text{cm}\)។ គណនាផ្ទៃក្រឡា។', NULL, '["\\(80\\ \\text{cm}^2\\)", "\\(36\\ \\text{cm}^2\\)", "\\(20\\ \\text{cm}^2\\)", "\\(40\\ \\text{cm}^2\\)"]', 3, NULL, 1, 'mcq', '\(S = \dfrac{10 \times 8}{2} = 40\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'easy', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9407, 'ចតុកោណខ្លែងមួយមានអង្កត់ទ្រូងកាត់គ្នាកែងប្រវែង \(14\ \text{cm}\) និង \(6\ \text{cm}\)។ គណនាផ្ទៃក្រឡារបស់វា។', NULL, '["\\(40\\ \\text{cm}^2\\)", "\\(84\\ \\text{cm}^2\\)", "\\(42\\ \\text{cm}^2\\)", "\\(20\\ \\text{cm}^2\\)"]', 2, NULL, 1, 'mcq', '\(S = \dfrac{14 \times 6}{2} = 42\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'easy', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9408, 'ការេមួយមានរង្វាស់ជ្រុង \(11\ \text{cm}\)។ គណនាផ្ទៃក្រឡានៃការេនោះ។', NULL, '["\\(121\\ \\text{cm}^2\\)", "\\(44\\ \\text{cm}^2\\)", "\\(110\\ \\text{cm}^2\\)", "\\(22\\ \\text{cm}^2\\)"]', 0, NULL, 1, 'mcq', '\(S = a^2 = 11^2 = 121\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'easy', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9409, 'ចតុកោណកែងមួយមានបណ្តោយ \(15\ \text{m}\) និងទទឹង \(8\ \text{m}\)។ គណនាផ្ទៃក្រឡារបស់វា។', NULL, '["\\(240\\ \\text{m}^2\\)", "\\(60\\ \\text{m}^2\\)", "\\(46\\ \\text{m}^2\\)", "\\(120\\ \\text{m}^2\\)"]', 3, NULL, 1, 'mcq', '\(S = 15 \times 8 = 120\ \text{m}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'easy', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9410, 'ចតុកោណព្នាយមួយមានបន្ទាត់មធ្យម \(m = 12\ \text{cm}\) និងកម្ពស់ \(h = 5\ \text{cm}\)។ គណនាផ្ទៃក្រឡារបស់វា។', NULL, '["\\(120\\ \\text{cm}^2\\)", "\\(30\\ \\text{cm}^2\\)", "\\(60\\ \\text{cm}^2\\)", "\\(17\\ \\text{cm}^2\\)"]', 2, NULL, 1, 'mcq', '\(S = m \times h = 12 \times 5 = 60\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'easy', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9411, 'ប្រលេឡូក្រាមមួយមានផ្ទៃក្រឡា \(72\ \text{cm}^2\) និងបាតប្រវែង \(9\ \text{cm}\)។ គណនាកម្ពស់ត្រូវគ្នានឹងបាតនេះ។', NULL, '["\\(9\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)", "\\(6\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\)"]', 3, NULL, 2, 'mcq', '\(h = \dfrac{S}{b} = \dfrac{72}{9} = 8\ \text{cm}\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9412, 'ចតុកោណព្នាយមួយមានផ្ទៃក្រឡា \(90\ \text{cm}^2\) និងបាតទាំងពីរមានរង្វាស់ \(8\ \text{cm}\) និង \(12\ \text{cm}\)។ គណនាកម្ពស់។', NULL, '["\\(9\\ \\text{cm}\\)", "\\(18\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)", "\\(4.5\\ \\text{cm}\\)"]', 0, NULL, 2, 'mcq', '\(h = \dfrac{2S}{a + b} = \dfrac{2 \times 90}{8 + 12} = \dfrac{180}{20} = 9\ \text{cm}\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9413, 'ចតុកោណព្នាយមួយមានផ្ទៃក្រឡា \(84\ \text{cm}^2\), កម្ពស់ \(7\ \text{cm}\) និងបាតមួយមានរង្វាស់ \(10\ \text{cm}\)។ គណនារង្វាស់បាតមួយទៀត។', NULL, '["\\(8\\ \\text{cm}\\)", "\\(14\\ \\text{cm}\\)", "\\(16\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)"]', 1, NULL, 2, 'mcq', '\(a + b = \dfrac{2S}{h} = \dfrac{168}{7} = 24 \Rightarrow b = 24 - 10 = 14\ \text{cm}\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9414, 'ចតុកោណស្មើមួយមានផ្ទៃក្រឡា \(60\ \text{cm}^2\) និងអង្កត់ទ្រូងមួយមានប្រវែង \(12\ \text{cm}\)។ គណនាប្រវែងអង្កត់ទ្រូងមួយទៀត។', NULL, '["\\(5\\ \\text{cm}\\)", "\\(15\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)"]', 3, NULL, 2, 'mcq', '\(d_2 = \dfrac{2S}{d_1} = \dfrac{2 \times 60}{12} = 10\ \text{cm}\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9415, 'ប្រលេឡូក្រាម \(ABCD\) មានជ្រុង \(AB = 15\ \text{cm}\) និង \(BC = 10\ \text{cm}\)។ កម្ពស់ត្រូវនឹងបាត \(AB\) គឺ \(6\ \text{cm}\)។ គណនាកម្ពស់ត្រូវនឹងបាត \(BC\)។', NULL, '["\\(8\\ \\text{cm}\\)", "\\(4\\ \\text{cm}\\)", "\\(9\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)"]', 2, NULL, 2, 'mcq', '\(S = 15 \times 6 = 90\ \text{cm}^2 \Rightarrow h_2 = \dfrac{90}{10} = 9\ \text{cm}\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9416, 'ចតុកោណព្នាយសមបាតមួយមានបាតតូច \(10\ \text{cm}\), បាតធំ \(22\ \text{cm}\) និងជ្រុងទ្រេត \(10\ \text{cm}\)។ គណនាផ្ទៃក្រឡា។', NULL, '["\\(128\\ \\text{cm}^2\\)", "\\(96\\ \\text{cm}^2\\)", "\\(160\\ \\text{cm}^2\\)", "\\(256\\ \\text{cm}^2\\)"]', 0, NULL, 2, 'mcq', '\(x = \dfrac{22 - 10}{2} = 6\ \text{cm} \Rightarrow h = \sqrt{10^2 - 6^2} = 8\ \text{cm}\)។ ផ្ទៃ ៖ \(S = \dfrac{(10+22) \times 8}{2} = 128\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9417, 'ចតុកោណព្នាយកែងមួយមានបាតទាំងពីរប្រវែង \(7.5\ \text{cm}\) និង \(12\ \text{cm}\) ហើយកម្ពស់ប្រវែង \(3\ \text{cm}\)។ គណនាផ្ទៃក្រឡា។', NULL, '["\\(24.5\\ \\text{cm}^2\\)", "\\(58.5\\ \\text{cm}^2\\)", "\\(32.5\\ \\text{cm}^2\\)", "\\(29.25\\ \\text{cm}^2\\)"]', 3, NULL, 2, 'mcq', '\(S = \dfrac{(7.5 + 12) \times 3}{2} = \dfrac{19.5 \times 3}{2} = 29.25\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9418, 'ចតុកោណស្មើមួយមានជ្រុងប្រវែង \(13\ \text{cm}\) និងអង្កត់ទ្រូងមួយប្រវែង \(24\ \text{cm}\)។ គណនាផ្ទៃក្រឡានៃចតុកោណស្មើ។', NULL, '["\\(60\\ \\text{cm}^2\\)", "\\(312\\ \\text{cm}^2\\)", "\\(240\\ \\text{cm}^2\\)", "\\(120\\ \\text{cm}^2\\)"]', 3, NULL, 2, 'mcq', 'កន្លះអង្កត់ទ្រូងទីពីរ ៖ \(\sqrt{13^2 - 12^2} = 5\ \text{cm} \Rightarrow d_2 = 10\ \text{cm}\)។ ផ្ទៃ ៖ \(S = \dfrac{24 \times 10}{2} = 120\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9419, 'ចម្ការកៅស៊ូមួយរាងចតុកោណកែងមានបណ្តោយ \(5\ \text{km}\) និងទទឹង \(2.3\ \text{km}\)។ គណនាផ្ទៃក្រឡាចម្ការគិតជាហិកតា (\(\text{ha}\))។', NULL, '["\\(1\\,150\\ \\text{ha}\\)", "\\(11.5\\ \\text{ha}\\)", "\\(11\\,500\\ \\text{ha}\\)", "\\(115\\ \\text{ha}\\)"]', 0, NULL, 2, 'mcq', '\(S = 5 \times 2.3 = 11.5\ \text{km}^2\)។ ដោយ \(1\ \text{km}^2 = 100\ \text{ha} \Rightarrow S = 11.5 \times 100 = 1\,150\ \text{ha}\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9420, 'សួនផ្កាកុលាបរាងត្រីកោណមានបាត \(5\ \text{m}\) និងកម្ពស់ \(3\ \text{m}\)។ បើដាំផ្កាកុលាប ១ ដើមត្រូវការផ្ទៃ \(0.5\ \text{m}^2\) តើគេអាចដាំផ្កាបានប៉ុន្មានដើម?', NULL, '["\\(10\\ \\text{ដើម}\\)", "\\(7.5\\ \\text{ដើម}\\)", "\\(15\\ \\text{ដើម}\\)", "\\(30\\ \\text{ដើម}\\)"]', 2, NULL, 2, 'mcq', '\(S = \dfrac{5 \times 3}{2} = 7.5\ \text{m}^2 \Rightarrow N = \dfrac{7.5}{0.5} = 15\ \text{ដើម}\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9421, 'ចតុកោណព្នាយមានបាត \(12\ \text{cm}\) និង \(16\ \text{cm}\) កម្ពស់ \(10\ \text{cm}\)។ គេកាត់ប្រហោងត្រីកោណបាត \(8\ \text{cm}\) និងកម្ពស់ \(10\ \text{cm}\) ចេញ។ រកផ្ទៃក្រឡាផ្នែកនៅសល់។', NULL, '["\\(40\\ \\text{cm}^2\\)", "\\(80\\ \\text{cm}^2\\)", "\\(100\\ \\text{cm}^2\\)", "\\(140\\ \\text{cm}^2\\)"]', 2, NULL, 2, 'mcq', '\(S_{\text{ព្នាយ}} = \dfrac{(12+16) \times 10}{2} = 140\); \(S_{\Delta} = \dfrac{8 \times 10}{2} = 40 \Rightarrow S = 140 - 40 = 100\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9422, 'ដីមួយកន្លែងរាងអក្សរ L បំបែកជាចតុកោណកែងពីរ ៖ មួយមានទំហំ \(9\ \text{m} \times 15\ \text{m}\) និងមួយទៀត \(12\ \text{m} \times 9\ \text{m}\)។ គណនាផ្ទៃក្រឡាសរុប។', NULL, '["\\(189\\ \\text{m}^2\\)", "\\(243\\ \\text{m}^2\\)", "\\(216\\ \\text{m}^2\\)", "\\(300\\ \\text{m}^2\\)"]', 1, NULL, 2, 'mcq', '\(S = (9 \times 15) + (12 \times 9) = 135 + 108 = 243\ \text{m}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9423, 'ក្រដាសរាងការេមួយមានជ្រុង \(9\ \text{cm}\)។ គេកាត់ជ្រុងទាំងបួនចេញជាត្រីកោណកែងសមបាតមានជ្រុងមុំកែង \(3\ \text{cm}\)។ គណនាផ្ទៃក្រឡាអដ្ឋកោណដែលនៅសល់។', NULL, '["\\(54\\ \\text{cm}^2\\)", "\\(72\\ \\text{cm}^2\\)", "\\(69\\ \\text{cm}^2\\)", "\\(63\\ \\text{cm}^2\\)"]', 3, NULL, 2, 'mcq', '\(S_{\text{ការេ}} = 9^2 = 81\); ផ្ទៃកាត់ ៖ \(4 \times \dfrac{3 \times 3}{2} = 18 \Rightarrow S = 81 - 18 = 63\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9424, 'ផ្ទៃជញ្ជាំងមុខផ្ទះផ្សំដោយចតុកោណកែង \(10\ \text{m} \times 6\ \text{m}\) និងត្រីកោណដំបូលខាងលើមានបាត \(10\ \text{m}\) និងកម្ពស់ \(4\ \text{m}\)។ គណនាផ្ទៃក្រឡាសរុប។', NULL, '["\\(80\\ \\text{m}^2\\)", "\\(70\\ \\text{m}^2\\)", "\\(85\\ \\text{m}^2\\)", "\\(100\\ \\text{m}^2\\)"]', 0, NULL, 2, 'mcq', '\(S = (10 \times 6) + \dfrac{10 \times 4}{2} = 60 + 20 = 80\ \text{m}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9425, 'ចតុកោណកែង \(ABCD\) មានវិមាត្រ \(25\ \text{cm} \times 17\ \text{cm}\) (ផ្ទៃ \(425\ \text{cm}^2\))។ គេគូសចតុកោណ \(PQRS\) នៅខាងក្នុងដោយបន្សល់ទុកត្រីកោណកែង 4 នៅជ្រុងដែលមានផ្ទៃរៀងគ្នា \(88\ \text{cm}^2,\ 22.5\ \text{cm}^2,\ 140\ \text{cm}^2,\ 4.5\ \text{cm}^2\)។ គណនាផ្ទៃក្រឡាចតុកោណ \(PQRS\)។', NULL, '["\\(180\\ \\text{cm}^2\\)", "\\(255\\ \\text{cm}^2\\)", "\\(160\\ \\text{cm}^2\\)", "\\(170\\ \\text{cm}^2\\)"]', 3, NULL, 3, 'mcq', 'ផលបូកផ្ទៃត្រីកោណទាំងបួន ៖ \(88 + 22.5 + 140 + 4.5 = 255\ \text{cm}^2\)។ ផ្ទៃក្រឡា \(PQRS = 425 - 255 = 170\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'hard', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9426, 'ចតុកោណស្មើមួយមានបរិមាត្រ \(52\ \text{cm}\) និងផលធៀបអង្កត់ទ្រូងទាំងពីរគឺ \(\dfrac{d_1}{d_2} = \dfrac{12}{5}\)។ គណនាផ្ទៃក្រឡារបស់វា។', NULL, '["\\(120\\ \\text{cm}^2\\)", "\\(130\\ \\text{cm}^2\\)", "\\(240\\ \\text{cm}^2\\)", "\\(60\\ \\text{cm}^2\\)"]', 0, NULL, 3, 'mcq', 'ជ្រុង \(a = 13\ \text{cm}\)។ តាង \(d_1 = 24x, d_2 = 10x \Rightarrow (12x)^2 + (5x)^2 = 13^2 \Rightarrow 13x = 13 \Rightarrow x = 1\) នាំឱ្យ \(S = \dfrac{24 \times 10}{2} = 120\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'hard', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9427, 'ចតុកោណព្នាយ \(ABCD\) (\(AB \parallel CD\)) មានបាត \(AB = 4\ \text{cm}\) និង \(CD = 8\ \text{cm}\)។ អង្កត់ទ្រូងកាត់គ្នាត្រង់ \(O\)។ តើផលធៀបផ្ទៃក្រឡា \(\dfrac{S_{\Delta OAB}}{S_{\Delta OCD}}\) ស្មើនឹងប៉ុន្មាន?', NULL, '["\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{1}{8}\\)", "\\(\\dfrac{1}{4}\\)", "\\(\\dfrac{1}{16}\\)"]', 2, NULL, 3, 'mcq', 'ត្រីកោណ \(\Delta OAB \sim \Delta OCD\) តាមផលធៀបដូច \(k = \dfrac{AB}{CD} = \dfrac{4}{8} = \dfrac{1}{2}\) នាំឱ្យផលធៀបផ្ទៃ \(k^2 = \dfrac{1}{4}\)', 'ផ្ទៃក្រឡាពហុកោណ', 'hard', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9428, 'ប្រលេឡូក្រាមមួយមានរង្វាស់ជ្រុងជាប់គ្នា \(8\ \text{cm}\) និង \(10\ \text{cm}\) ហើយមុំស្រួចមួយមានរង្វាស់ \(30^\circ\)។ គណនាផ្ទៃក្រឡានៃប្រលេឡូក្រាមនោះ។', NULL, '["\\(40\\sqrt{3}\\ \\text{cm}^2\\)", "\\(40\\ \\text{cm}^2\\)", "\\(80\\ \\text{cm}^2\\)", "\\(20\\ \\text{cm}^2\\)"]', 1, NULL, 3, 'mcq', '\(h = 8 \times \sin 30^\circ = 8 \times 0.5 = 4\ \text{cm} \Rightarrow S = 10 \times 4 = 40\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'hard', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9429, 'ត្រីកោណសម័ង្សមួយមានរង្វាស់ជ្រុង \(6\ \text{cm}\)។ គណនាផ្ទៃក្រឡារបស់វា។', NULL, '["\\(9\\sqrt{3}\\ \\text{cm}^2\\)", "\\(36\\sqrt{3}\\ \\text{cm}^2\\)", "\\(12\\ \\text{cm}^2\\)", "\\(18\\sqrt{3}\\ \\text{cm}^2\\)"]', 0, NULL, 3, 'mcq', '\(S = \dfrac{\sqrt{3}}{4} \times 6^2 = \dfrac{36\sqrt{3}}{4} = 9\sqrt{3}\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'hard', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9430, 'ឆកោណទៀងទាត់មួយមានរង្វាស់ជ្រុង \(4\ \text{cm}\)។ គណនាផ្ទៃក្រឡានៃឆកោណទៀងទាត់នោះ។', NULL, '["\\(48\\sqrt{3}\\ \\text{cm}^2\\)", "\\(24\\sqrt{3}\\ \\text{cm}^2\\)", "\\(36\\ \\text{cm}^2\\)", "\\(16\\sqrt{3}\\ \\text{cm}^2\\)"]', 1, NULL, 3, 'mcq', 'ឆកោណទៀងទាត់ផ្គុំដោយត្រីកោណសម័ង្សចំនួន 6 ៖ \(S = 6 \times \left(\dfrac{\sqrt{3}}{4} \times 4^2\right) = 6 \times 4\sqrt{3} = 24\sqrt{3}\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'hard', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9431, 'បន្ទះដែកមួយរាងចតុកោណកែងទំហំ \(24\ \text{cm} \times 42\ \text{cm}\) (ផ្ទៃ \(1\,008\ \text{cm}^2\))។ គេកាត់ចេញនូវការេជ្រុង \(8\ \text{cm}\) មួយ និងត្រីកោណកែងជ្រុង \(14\ \text{cm} \times 26\ \text{cm}\) មួយ។ គណនាផ្ទៃដែកដែលនៅសល់។', NULL, '["\\(826\\ \\text{cm}^2\\)", "\\(762\\ \\text{cm}^2\\)", "\\(740\\ \\text{cm}^2\\)", "\\(698\\ \\text{cm}^2\\)"]', 1, NULL, 3, 'mcq', '\(S = 1\,008 - 8^2 - \dfrac{14 \times 26}{2} = 1\,008 - 64 - 182 = 762\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'hard', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9432, 'ជ្រុងម្ខាងនៃអគាររាងចតុកោណព្នាយមានបាតដី \(400\ \text{m}\), ដំបូល \(150\ \text{m}\) និងកម្ពស់ \(500\ \text{m}\)។ បើគេបិទកញ្ចក់ដែលមួយផ្ទាំងមានផ្ទៃ \(1\ \text{m}^2\) តើត្រូវប្រើកញ្ចក់ប៉ុន្មានផ្ទាំង?', NULL, '["\\(135\\,000\\ \\text{ផ្ទាំង}\\)", "\\(275\\,000\\ \\text{ផ្ទាំង}\\)", "\\(140\\,000\\ \\text{ផ្ទាំង}\\)", "\\(137\\,500\\ \\text{ផ្ទាំង}\\)"]', 3, NULL, 3, 'mcq', '\(S = \dfrac{(400 + 150) \times 500}{2} = 550 \times 250 = 137\,500\ \text{m}^2 \Rightarrow N = 137\,500\ \text{ផ្ទាំង}\)', 'ផ្ទៃក្រឡាពហុកោណ', 'pisa', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9433, 'ផ្លូវចូលផ្ទះរាងចតុកោណព្នាយមានបាតទាំងពីរ \(12\ \text{m}\) និង \(8\ \text{m}\) ហើយកម្ពស់ \(15\ \text{m}\)។ បើថ្លៃចាក់បេតុងក្រាលផ្លូវគឺ \(18\$/\text{m}^2\) គណនាថ្លៃចំណាយសរុប។', NULL, '["\\(5\\,400\\$\\)", "\\(2\\,400\\$\\)", "\\(3\\,240\\$\\)", "\\(2\\,700\\$\\)"]', 3, NULL, 3, 'mcq', '\(S = \dfrac{(12 + 8) \times 15}{2} = 150\ \text{m}^2 \Rightarrow \text{ថ្លៃ} = 150 \times 18 = 2\,700\$\)', 'ផ្ទៃក្រឡាពហុកោណ', 'pisa', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9434, 'ស្រែរាងប្រលេឡូក្រាមមួយមានបាត \(120\ \text{m}\) និងកម្ពស់ \(75\ \text{m}\)។ បើទិន្នផលស្រូវជាមធ្យមទទួលបាន \(5.5\ \text{តោន/ហិកតា}\) គណនាបរិមាណស្រូវប្រមូលផលបានពីស្រែនេះ។', NULL, '["\\(49.5\\ \\text{តោន}\\)", "\\(5.5\\ \\text{តោន}\\)", "\\(4.95\\ \\text{តោន}\\)", "\\(9.9\\ \\text{តោន}\\)"]', 2, NULL, 3, 'mcq', '\(S = 120 \times 75 = 9\,000\ \text{m}^2 = 0.9\ \text{ha} \Rightarrow \text{ផល} = 0.9 \times 5.5 = 4.95\ \text{តោន}\)', 'ផ្ទៃក្រឡាពហុកោណ', 'pisa', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9435, 'ខ្លែងមួយរាងចតុកោណខ្លែងមានអង្កត់ទ្រូង \(50\ \text{cm}\) និង \(30\ \text{cm}\)។ ដោយសារការកាត់គែមបិទភ្ជាប់ គេត្រូវប្រើក្រដាសលើសផ្ទៃខ្លែង \(20\%\)។ គណនាផ្ទៃក្រដាសដែលត្រូវប្រើ។', NULL, '["\\(1\\,000\\ \\text{cm}^2\\)", "\\(850\\ \\text{cm}^2\\)", "\\(900\\ \\text{cm}^2\\)", "\\(750\\ \\text{cm}^2\\)"]', 2, NULL, 3, 'mcq', '\(S = \dfrac{50 \times 30}{2} = 750\ \text{cm}^2 \Rightarrow S_{\text{ក្រដាស}} = 750 \times 1.20 = 900\ \text{cm}^2\)', 'ផ្ទៃក្រឡាពហុកោណ', 'pisa', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9436, 'ដំបូលរោងចក្ររាងចតុកោណព្នាយមានបាត \(10\ \text{m}\) និង \(6\ \text{m}\) កម្ពស់ \(4\ \text{m}\)។ គេចង់ដំឡើងផ្ទាំងសូឡាទំហំ \(1.6\ \text{m}^2\) លើផ្ទៃដំបូល \(80\%\)។ តើដំឡើងបានប៉ុន្មានផ្ទាំង?', NULL, '["\\(20\\ \\text{ផ្ទាំង}\\)", "\\(12\\ \\text{ផ្ទាំង}\\)", "\\(16\\ \\text{ផ្ទាំង}\\)", "\\(25\\ \\text{ផ្ទាំង}\\)"]', 2, NULL, 3, 'mcq', '\(S = \dfrac{(10 + 6) \times 4}{2} = 32\ \text{m}^2\); ផ្ទៃសូឡា ៖ \(32 \times 0.8 = 25.6\ \text{m}^2 \Rightarrow N = \dfrac{25.6}{1.6} = 16\ \text{ផ្ទាំង}\)', 'ផ្ទៃក្រឡាពហុកោណ', 'pisa', 1, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9437, 'ប្រលេឡូក្រាម \(ABCD\) មួយមានបាត \(b = 14\ \text{cm}\) និងកម្ពស់ត្រូវគ្នា \(h = 8\ \text{cm}\)។
ក. សរសេររូបមន្តគណនាផ្ទៃក្រឡាប្រលេឡូក្រាម។
ខ. គណនាផ្ទៃក្រឡានៃប្រលេឡូក្រាមនោះ។
គ. បញ្ជាក់ខ្នាតនៃផ្ទៃក្រឡាឱ្យបានត្រឹមត្រូវ។', 'g8-12ddd0273b.svg', '[]', 0, NULL, 5, 'writing', 'ក. រូបមន្តផ្ទៃក្រឡាប្រលេឡូក្រាម ៖ \(S = b \times h\) (2 ពិន្ទុ)
ខ. ជំនួសតម្លៃ ៖ \(S = 14 \times 8 = 112\) (2 ពិន្ទុ)
គ. ខ្នាតផ្ទៃក្រឡាគឺ សង់ទីម៉ែត្រការេ (\(\text{cm}^2\)) ដូចនេះ \(S = 112\ \text{cm}^2\) (1 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'easy', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9438, 'បង្ហាញរូបមន្តផ្ទៃក្រឡាចតុកោណព្នាយ \(ABCD\) (\(AB \parallel CD\)) ដែលមានបាត \(AB = a\), \(CD = b\) និងកម្ពស់ \(h\)។
ក. គូសអង្កត់ទ្រូង \(AC\) បំបែកចតុកោណព្នាយជាត្រីកោណពីរណាខ្លះ?
ខ. គណនាផ្ទៃក្រឡានៃត្រីកោណទាំងពីរនោះជាអនុគមន៍នៃ \(a, b, h\)។
គ. ទាញរកផ្ទៃក្រឡាចតុកោណព្នាយ \(S = \dfrac{(a + b)h}{2}\)។', 'g8-7d9add613a.svg', '[]', 0, NULL, 5, 'writing', 'ក. អង្កត់ទ្រូង \(AC\) បំបែកចតុកោណព្នាយជាត្រីកោណពីរគឺ \(\Delta ABC\) និង \(\Delta ADC\) (1 ពិន្ទុ)
ខ. ផ្ទៃ \(S_{\Delta ADC} = \dfrac{b \times h}{2}\) និងផ្ទៃ \(S_{\Delta ABC} = \dfrac{a \times h}{2}\) (2 ពិន្ទុ)
គ. ផ្ទៃសរុប \(S = S_{\Delta ADC} + S_{\Delta ABC} = \dfrac{bh}{2} + \dfrac{ah}{2} = \dfrac{(a + b)h}{2}\) (2 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9439, 'ចតុកោណស្មើ \(ABCD\) មានអង្កត់ទ្រូងកាត់គ្នាកែងត្រង់ \(O\) ដោយ \(AC = 18\ \text{cm}\) និង \(BD = 12\ \text{cm}\)។
ក. សរសេររូបមន្ត និងគណនាផ្ទៃក្រឡានៃចតុកោណស្មើ។
ខ. គណនាប្រវែងកន្លះអង្កត់ទ្រូង \(OA\) និង \(OB\)។
គ. គណនាប្រវែងជ្រុង \(AB\) និងបរិមាត្រ \(P\) ជាទម្រង់រ៉ាឌីកាល់សម្រួល។', 'g8-1c3519bad0.svg', '[]', 0, NULL, 5, 'writing', 'ក. រូបមន្ត ៖ \(S = \dfrac{d_1 \times d_2}{2} = \dfrac{18 \times 12}{2} = 108\ \text{cm}^2\) (2 ពិន្ទុ)
ខ. កន្លះអង្កត់ទ្រូង ៖ \(OA = \dfrac{18}{2} = 9\ \text{cm}\) និង \(OB = \dfrac{12}{2} = 6\ \text{cm}\) (1 ពិន្ទុ)
គ. ជ្រុង \(AB = \sqrt{9^2 + 6^2} = \sqrt{81 + 36} = \sqrt{117} = 3\sqrt{13}\ \text{cm}\) នាំឱ្យបរិមាត្រ \(P = 4 \times 3\sqrt{13} = 12\sqrt{13}\ \text{cm}\) (2 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9440, 'ប្រលេឡូក្រាម \(ABCD\) មានជ្រុង \(AB = 20\ \text{cm}\) និង \(AD = 12\ \text{cm}\)។ កម្ពស់ត្រូវនឹងបាត \(AB\) គឺ \(h_1 = 9\ \text{cm}\)។
ក. គណនាផ្ទៃក្រឡានៃប្រលេឡូក្រាម \(ABCD\)។
ខ. សរសេរសមីការទំនាក់ទំនងផ្ទៃក្រឡាធៀបនឹងបាត \(AD\) និងកម្ពស់ \(h_2\)។
គ. គណនាកម្ពស់ \(h_2\) ត្រូវនឹងបាត \(AD\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃក្រឡា ៖ \(S = AB \times h_1 = 20 \times 9 = 180\ \text{cm}^2\) (2 ពិន្ទុ)
ខ. សមីការ ៖ \(S = AD \times h_2 \Rightarrow 180 = 12 \times h_2\) (1 ពិន្ទុ)
គ. ទាញបាន \(h_2 = \dfrac{180}{12} = 15\ \text{cm}\) (2 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9441, 'ចតុកោណព្នាយកែង \(ABCD\) (\(ngle A = ngle D = 90^\circ\)) មានបាតតូច \(AB = 8\ \text{cm}\), បាតធំ \(CD = 14\ \text{cm}\) និងជ្រុងទ្រេត \(BC = 10\ \text{cm}\)។
ក. គូសកម្ពស់ \(BH \perp CD\) រួចគណនាប្រវែងកំណាត់ \(HC\)។
ខ. គណនាកម្ពស់ \(h = BH\)។
គ. គណនាផ្ទៃក្រឡានៃចតុកោណព្នាយកែង \(ABCD\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ដោយ \(ABHD\) ជាចតុកោណកែង នោះ \(DH = AB = 8\ \text{cm} \Rightarrow HC = CD - DH = 14 - 8 = 6\ \text{cm}\) (1 ពិន្ទុ)
ខ. ក្នុងត្រីកោណកែង \(BHC\) ៖ \(BH = \sqrt{BC^2 - HC^2} = \sqrt{10^2 - 6^2} = 8\ \text{cm}\) (2 ពិន្ទុ)
គ. ផ្ទៃក្រឡា ៖ \(S = \dfrac{(AB + CD) \times BH}{2} = \dfrac{(8 + 14) \times 8}{2} = 88\ \text{cm}^2\) (2 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'medium', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9442, 'ចតុកោណព្នាយសមបាត \(ABCD\) មានបាតតូច \(AB = 14\ \text{cm}\), បាតធំ \(CD = 30\ \text{cm}\) និងជ្រុងទ្រេត \(AD = BC = 17\ \text{cm}\)។
ក. គណនាប្រវែងចំណោលកែង \(x\) នៃជ្រុងទ្រេតលើបាតធំ។
ខ. គណនាកម្ពស់ \(h\) នៃចតុកោណព្នាយ។
គ. គណនាផ្ទៃក្រឡា និងបរិមាត្រនៃចតុកោណព្នាយ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ចំណោលកែង ៖ \(x = \dfrac{CD - AB}{2} = \dfrac{30 - 14}{2} = 8\ \text{cm}\) (1 ពិន្ទុ)
ខ. តាមពីតាក័រ ៖ \(h = \sqrt{17^2 - 8^2} = \sqrt{289 - 64} = \sqrt{225} = 15\ \text{cm}\) (2 ពិន្ទុ)
គ. ផ្ទៃ ៖ \(S = \dfrac{(14 + 30) \times 15}{2} = 330\ \text{cm}^2\); បរិមាត្រ ៖ \(P = 14 + 30 + 2(17) = 78\ \text{cm}\) (2 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'hard', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9443, 'ចតុកោណកែងធំ \(ABCD\) មួយមានវិមាត្រ \(25\ \text{cm} \times 17\ \text{cm}\)។ ចំណុច \(P, Q, R, S\) ស្ថិតនៅលើជ្រុងទាំងបួន បង្កើតបានចតុកោណ \(PQRS\) និងត្រីកោណកែង 4 នៅជ្រុងទាំងបួនដែលមានផ្ទៃរៀងគ្នា \(S_1 = 88\ \text{cm}^2\), \(S_2 = 22.5\ \text{cm}^2\), \(S_3 = 140\ \text{cm}^2\) និង \(S_4 = 4.5\ \text{cm}^2\)។
ក. គណនាផ្ទៃក្រឡាសរុបនៃចតុកោណកែង \(ABCD\)។
ខ. គណនាផលបូកផ្ទៃក្រឡានៃត្រីកោណកែងទាំងបួន។
គ. ទាញរកផ្ទៃក្រឡានៃចតុកោណ \(PQRS\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃក្រឡាចតុកោណកែង ៖ \(S_{\text{ធំ}} = 25 \times 17 = 425\ \text{cm}^2\) (1 ពិន្ទុ)
ខ. ផលបូកផ្ទៃត្រីកោណទាំងបួន ៖ \(S_{\text{បួន}} = 88 + 22.5 + 140 + 4.5 = 255\ \text{cm}^2\) (2 ពិន្ទុ)
គ. ផ្ទៃក្រឡាចតុកោណ \(PQRS = S_{\text{ធំ}} - S_{\text{បួន}} = 425 - 255 = 170\ \text{cm}^2\) (2 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'hard', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9444, 'ចតុកោណខ្លែង \(ABCD\) មានអង្កត់ទ្រូងពីរកាត់គ្នាកែងត្រង់ \(O\) (\(AC \perp BD\))។
ក. បង្ហាញថាអង្កត់ទ្រូង \(AC\) ចែកចតុកោណខ្លែងជាត្រីកោណពីរ \(\Delta ABC\) និង \(\Delta ADC\) ដែលមានបាតរួម \(AC\)។
ខ. សរសេរកន្សោមផ្ទៃក្រឡានៃត្រីកោណទាំងពីរជាអនុគមន៍នៃ \(AC, OB\) និង \(OD\)។
គ. បង្ហាញថាផ្ទៃក្រឡាចតុកោណខ្លែងគឺ \(S = \dfrac{AC \times BD}{2}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. អង្កត់ទ្រូង \(AC\) ចែកចតុកោណជា \(\Delta ABC\) និង \(\Delta ADC\) ដែលមានបាតរួម \(AC\) និងកម្ពស់រៀងគ្នា \(OB, OD\) (ព្រោះ \(BD \perp AC\)) (2 ពិន្ទុ)
ខ. \(S_{ABC} = \dfrac{1}{2} AC \times OB\) និង \(S_{ADC} = \dfrac{1}{2} AC \times OD\) (1 ពិន្ទុ)
គ. \(S = S_{ABC} + S_{ADC} = \dfrac{1}{2} AC (OB + OD) = \dfrac{1}{2} AC \times BD = \dfrac{AC \times BD}{2}\) (2 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'hard', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9445, 'ដីឡូត៍មួយមានរាងអក្សរ L ដែលមានវិមាត្រខាងក្រៅ ៖ បណ្តោយសរុប \(21\ \text{m}\), ទទឹងសរុប \(15\ \text{m}\)។ គេអាចបំបែកដីនេះជាចតុកោណកែងពីរ ៖ ចតុកោណកែងទី១ ទំហំ \(9\ \text{m} \times 15\ \text{m}\) និងចតុកោណកែងទី២ ទំហំ \(12\ \text{m} \times 9\ \text{m}\)។
ក. គណនាផ្ទៃក្រឡានៃចតុកោណកែងនីមួយៗ។
ខ. គណនាផ្ទៃក្រឡាសរុបនៃដីឡូត៍នោះ។
គ. គណនាបរិមាត្រជុំវិញនៃដីឡូត៍ (ដឹងថាជ្រុងទាំង 6 មានប្រវែង \(21\ \text{m}, 15\ \text{m}, 9\ \text{m}, 6\ \text{m}, 12\ \text{m}, 9\ \text{m}\))។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃទី១ ៖ \(S_1 = 9 \times 15 = 135\ \text{m}^2\); ផ្ទៃទី២ ៖ \(S_2 = 12 \times 9 = 108\ \text{m}^2\) (2 ពិន្ទុ)
ខ. ផ្ទៃសរុប ៖ \(S = S_1 + S_2 = 135 + 108 = 243\ \text{m}^2\) (1 ពិន្ទុ)
គ. បរិមាត្រ ៖ \(P = 21 + 15 + 9 + 6 + 12 + 9 = 72\ \text{m}\) (2 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'hard', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9446, 'ចម្ការកៅស៊ូមួយកន្លែងរាងចតុកោណកែងមានបណ្តោយប្រវែង \(5\ \text{km}\) និងទទឹងប្រវែង \(2.3\ \text{km}\)។
ក. គណនាផ្ទៃក្រឡាចម្ការគិតជាគីឡូម៉ែត្រការេ (\(\text{km}^2\))។
ខ. បំលែងផ្ទៃក្រឡានោះទៅជាហិកតា (\(\text{ha}\)) ដោយដឹងថា \(1\ \text{km}^2 = 100\ \text{ha}\)។
គ. បើចម្ការនេះអាចទាញយកជ័រកៅស៊ូជាមធ្យម \(1.8\ \text{តោន/ហិកតា}\) ក្នុងមួយឆ្នាំ គណនាទិន្នផលជ័រប្រចាំឆ្នាំសរុប។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃក្រឡាជាគីឡូម៉ែត្រការេ ៖ \(S = 5\ \text{km} \times 2.3\ \text{km} = 11.5\ \text{km}^2\) (2 ពិន្ទុ)
ខ. បំលែងជាហិកតា ៖ \(S = 11.5 \times 100 = 1\,150\ \text{ha}\) (2 ពិន្ទុ)
គ. ទិន្នផលប្រចាំឆ្នាំសរុប ៖ \(1\,150 \times 1.8 = 2\,070\ \text{តោន}\) (1 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'pisa', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9447, 'សួនច្បារផ្កាកុលាបមួយរាងត្រីកោណមានបាត \(5\ \text{m}\) និងកម្ពស់ \(3\ \text{m}\)។
ក. គណនាផ្ទៃក្រឡាសួនច្បាររាងត្រីកោណនេះ។
ខ. បើគេដាំផ្កាកុលាប ១ ដើម ត្រូវការផ្ទៃដី \(0.5\ \text{m}^2\) តើគេអាចដាំផ្កាកុលាបបានប៉ុន្មានដើមក្នុងសួននេះ?
គ. បើកូនផ្កាកុលាបមួយដើមថ្លៃ \(2.50\$\) គណនាថ្លៃទិញកូនផ្កាទាំងអស់សម្រាប់ដាំក្នុងសួន។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃក្រឡាសួនច្បារ ៖ \(S = \dfrac{1}{2} \times 5 \times 3 = 7.5\ \text{m}^2\) (2 ពិន្ទុ)
ខ. ចំនួនដើមផ្កាកុលាបដែលអាចដាំបាន ៖ \(N = \dfrac{7.5\ \text{m}^2}{0.5\ \text{m}^2} = 15\ \text{ដើម}\) (2 ពិន្ទុ)
គ. ថ្លៃទិញកូនផ្កាសរុប ៖ \(15 \times 2.50 = 37.50\$\) (1 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'pisa', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9448, 'ជ្រុងម្ខាងនៃអគាររាងចតុកោណព្នាយមួយមានបាតក្រោមប្រវែង \(400\ \text{m}\), បាតលើ (ដំបូល) ប្រវែង \(150\ \text{m}\) និងកម្ពស់ប្រវែង \(500\ \text{m}\)។
ក. គណនាផ្ទៃក្រឡាជញ្ជាំងជ្រុងអគារនោះ។
ខ. បើគេបិទកញ្ចក់ការពារកម្តៅថ្ងៃដែលមួយផ្ទាំងមានផ្ទៃ \(1\ \text{m}^2\) តើត្រូវប្រើកញ្ចក់អស់ប៉ុន្មានផ្ទាំង?
គ. បើតម្លៃកញ្ចក់រួមទាំងថ្លៃដំឡើងគឺ \(45\$/\text{m}^2\) គណនាថវិកាសរុបដែលត្រូវចំណាយ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃក្រឡាជញ្ជាំងអគារ ៖ \(S = \dfrac{(400 + 150) \times 500}{2} = \dfrac{550 \times 500}{2} = 137\,500\ \text{m}^2\) (2 ពិន្ទុ)
ខ. ចំនួនផ្ទាំងកញ្ចក់ដែលត្រូវប្រើ ៖ \(N = \dfrac{137\,500\ \text{m}^2}{1\ \text{m}^2} = 137\,500\ \text{ផ្ទាំង}\) (1 ពិន្ទុ)
គ. ថវិកាសរុប ៖ \(137\,500 \times 45 = 6\,187\,500\$\) (2 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'pisa', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9449, 'ដំបូលរោងចក្រមួយផ្នែកមានរាងចតុកោណព្នាយសមបាតមានបាតក្រោម \(16\ \text{m}\), បាតលើ \(10\ \text{m}\) និងកម្ពស់ជម្រាល \(6\ \text{m}\)។
ក. គណនាផ្ទៃក្រឡានៃផ្នែកដំបូលនោះមួយផ្ទាំង។
ខ. បើដំបូលនោះមាន ២ ផ្ទាំងដូចគ្នា គណនាផ្ទៃក្រឡាដំបូលសរុប។
គ. បើ ១ ម៉ែត្រការេត្រូវប្រើក្បឿង ១២ សន្លឹក ហើយគេត្រូវទិញបន្ថែម \(5\%\) សម្រាប់កាត់គែមនិងបាក់បែក តើត្រូវទិញក្បឿងសរុបប៉ុន្មានសន្លឹក?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃមួយផ្ទាំង ៖ \(S_1 = \dfrac{(16 + 10) \times 6}{2} = \dfrac{26 \times 6}{2} = 78\ \text{m}^2\) (2 ពិន្ទុ)
ខ. ផ្ទៃសរុប ២ ផ្ទាំង ៖ \(S = 78 \times 2 = 156\ \text{m}^2\) (1 ពិន្ទុ)
គ. ចំនួនក្បឿងត្រូវការ ៖ \(156 \times 12 = 1\,872\ \text{សន្លឹក}\)។ ទិញបន្ថែម \(5\%\) ៖ \(1\,872 \times 1.05 = 1\,965.6 pprox 1\,966\ \text{សន្លឹក}\) (2 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'pisa', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9450, 'ដីស្រែរាងចតុកោណព្នាយ \(ABCD\) (\(AB \parallel CD\)) មានបាត \(AB = 40\ \text{m}\), \(CD = 80\ \text{m}\) និងកម្ពស់ \(30\ \text{m}\)។
ក. គណនាផ្ទៃក្រឡាដីស្រែសរុប។
ខ. ម្ចាស់ដីចែកដីជាពីរចំណែកដោយគូសបន្ទាត់ស្រប \(BE \parallel AD\) (\(E \in CD\)) បង្កើតបានប្រលេឡូក្រាម \(ABED\) និងត្រីកោណ \(BCE\)។ គណនាផ្ទៃក្រឡាចំណែកនីមួយៗ។
គ. ផ្ទៀងផ្ទាត់ផលបូកផ្ទៃក្រឡាទាំងពីរធៀបនឹងផ្ទៃសរុប។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃស្រែសរុប ៖ \(S = \dfrac{(40 + 80) \times 30}{2} = \dfrac{120 \times 30}{2} = 1\,800\ \text{m}^2\) (2 ពិន្ទុ)
ខ. \(ED = AB = 40\ \text{m} \Rightarrow EC = 80 - 40 = 40\ \text{m}\)។ ផ្ទៃប្រលេឡូក្រាម \(S_1 = 40 \times 30 = 1\,200\ \text{m}^2\); ផ្ទៃត្រីកោណ \(S_2 = \dfrac{40 \times 30}{2} = 600\ \text{m}^2\) (2 ពិន្ទុ)
គ. ផ្ទៀងផ្ទាត់ ៖ \(S_1 + S_2 = 1\,200 + 600 = 1\,800\ \text{m}^2 = S\) (ត្រឹមត្រូវ) (1 ពិន្ទុ)', 'ផ្ទៃក្រឡាពហុកោណ', 'pisa', 0, '8', 'ផ្ទៃក្រឡាពហុកោណ', NULL, 0);
